tm = TimeMap(clock=clock)
tm.set("probe-1", 68.0)
clock.advance(40.0)
tm.set("probe-1", 71.5)
assert tm.get("probe-1") == 71.5
assert tm.get("probe-1", 1000.0) == 68.0
